using KBS.BLL.Interfaces; using KBS.DAL.Data; using KBS.Models.DTOs.Brands; using KBS.Models.Entities; using Microsoft.EntityFrameworkCore;
namespace KBS.BLL.Services;
public class BrandService(KbsDbContext db) : IBrandService
{ public async Task<List<BrandResponseDto>> GetAllAsync(CancellationToken ct=default){var brands=await db.Brands.AsNoTracking().OrderBy(x=>x.Name).ToListAsync(ct);return brands.Select(ToDto).ToList();} public async Task<BrandResponseDto?> GetByIdAsync(long id,CancellationToken ct=default){var brand=await db.Brands.AsNoTracking().FirstOrDefaultAsync(x=>x.Id==id,ct);return brand is null?null:ToDto(brand);}
 public async Task<BrandResponseDto> CreateAsync(BrandCreateDto dto,CancellationToken ct=default){var name=ValidateName(dto.Name); if(await db.Brands.AnyAsync(x=>x.Name.ToLower()==name.ToLower(),ct))throw new InvalidOperationException("Tên thương hiệu đã tồn tại.");var brand=new Brand{Name=name,Description=dto.Description?.Trim(),IsActive=dto.IsActive};db.Brands.Add(brand);await db.SaveChangesAsync(ct);return ToDto(brand);}
 public async Task<BrandResponseDto?> UpdateAsync(long id,BrandUpdateDto dto,CancellationToken ct=default){var brand=await db.Brands.FindAsync([id],ct);if(brand is null)return null;var name=ValidateName(dto.Name);if(await db.Brands.AnyAsync(x=>x.Id!=id&&x.Name.ToLower()==name.ToLower(),ct))throw new InvalidOperationException("Tên thương hiệu đã tồn tại.");brand.Name=name;brand.Description=dto.Description?.Trim();brand.IsActive=dto.IsActive;await db.SaveChangesAsync(ct);return ToDto(brand);} private static string ValidateName(string n)=>string.IsNullOrWhiteSpace(n)?throw new ArgumentException("Tên thương hiệu không được để trống."):n.Trim(); private static BrandResponseDto ToDto(Brand x)=>new(){Id=x.Id,Name=x.Name,Description=x.Description,IsActive=x.IsActive,CreatedAt=x.CreatedAt}; }
